#include <stdio.h>
#include <string.h>
#include <ctype.h>

int main(int argc, char **argv) {
    const char *in;
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }
    in = argv[1];
    size_t len = strlen(in);
    if (len > 1024) len = 1024; // limit processing to first 1024 characters
    char out[1025]; // enough for trimmed string plus null terminator
    size_t out_idx = 0;
    size_t i = 0;
    // Skip leading whitespace
    while (i < len && isspace((unsigned char)in[i])) {
        i++;
    }
    int in_whitespace = 0; // flag indicating we are in a run of whitespace
    for (; i < len; ++i) {
        char c = in[i];
        if (isspace((unsigned char)c)) {
            in_whitespace = 1;
        } else {
            if (out_idx > 0 && in_whitespace) {
                out[out_idx++] = ' ';
            }
            out[out_idx++] = c;
            in_whitespace = 0;
        }
    }
    out[out_idx] = '\0';
    if (out_idx == 0) {
        puts("EMPTY");
    } else {
        puts(out);
    }
    return 0;
}
